CREATE TABLE IF NOT EXISTS ERP.EKPO
(
 EBELN     char(10) NOT NULL COMMENT 'Unique identifier for the purchasing document; links to the EKKO table.',
 EBELP     char(5) NOT NULL COMMENT 'Sequential number of the item within the purchasing document.',
 MATNR     char(18) COMMENT 'Identifier for the material; links to the MARA table.',
 MENGE     decimal(13,3) COMMENT 'Quantity Ordered',
